INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('cao-pi', '曹丕', ARRAY[]::text[], NULL, NULL, 187, 1, 226, 6, ARRAY['皇帝'], '曹操之子，承袭魏王后于220年受汉献帝禅让称帝，建立曹魏，在位至226年。他延续父亲奠定的北方政权，并以九品中正制等措施整顿选官；其子曹叡继位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹丕"}]'::jsonb, '文皇帝', '高祖', '魏文帝')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('cao-rui', '曹叡', ARRAY[]::text[], NULL, NULL, 206, 1, 239, 1, ARRAY['皇帝'], '曹丕之子，226—239年在位，是曹魏第二帝。即位后面对蜀汉、孙吴的持续攻势，主持防御与政务；因无亲生子，临终托孤并立养子曹芳为帝，由曹爽、司马懿辅政。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹叡"}]'::jsonb, '明皇帝', '烈祖', '魏明帝')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('liu-bei', '刘备', ARRAY[]::text[], NULL, NULL, 161, 1, 223, 6, ARRAY['皇帝'], '汉景帝之子中山靖王刘胜之后，长期辗转于群雄之间，后据有益州。221年在成都称帝、国号汉，史称蜀汉；次年为报关羽之仇伐吴，夷陵之战败后退守永安，223年去世并由刘禅继位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘备"}]'::jsonb, '昭烈皇帝', '烈祖', '昭烈帝')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('liu-shan', '刘禅', ARRAY[]::text[], NULL, NULL, 207, 1, 271, 1, ARRAY['皇帝'], '刘备之子，223年继位，在位至263年，是蜀汉第二帝。刘备去世后由诸葛亮辅政，诸葛亮及其后蒋琬、费祎、姜维等先后主持国政；263年魏军攻入蜀地，刘禅向邓艾投降，蜀汉灭亡。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘禅"}]'::jsonb, '孝怀皇帝', NULL, '蜀汉后主')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('sun-quan', '孙权', ARRAY[]::text[], NULL, NULL, 182, 7, 252, 5, ARRAY['皇帝'], '孙坚之子、孙策之弟，承接孙策经营的江东基业，逐步确立对长江中下游及岭南部分地区的统治。208年与刘备结盟，在赤壁之战中击退曹操；222年受封吴王，229年称帝，在位至252年，孙吴由其子孙继续统治。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙权"}]'::jsonb, '大皇帝', '太祖', '大皇帝')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, death_year, death_month, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('zhuge-liang', '诸葛亮', ARRAY[]::text[], NULL, NULL, 181, 1, 234, 8, ARRAY['政治家','军事家'], '蜀汉丞相，赤壁之战参与者，后主朝北伐。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/诸葛亮"}]'::jsonb, NULL, NULL, NULL)
