VALUES ('liu-zhang', '刘璋', ARRAY[]::text[], NULL, NULL, 176, 1, 219, 1, ARRAY['军阀'], '益州牧，刘焉之子；引刘备入蜀后失益州，东汉末地方势力。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘璋"}]'::jsonb, NULL, NULL, NULL)
