-- dynasties
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, end_year, end_month, start_abs, end_abs, precision, color_token, parent_id, group_id, note)
VALUES ('wei', '曹魏', ARRAY['魏'], 'cn', 'east_asia', 220, 12, 266, 2, 2651, 3193, 'month', 'ochre', NULL, 'sanguo', '220年曹丕受汉献帝禅让称帝，国号魏，史称曹魏；以洛阳为都，主要统治中国北方，与蜀汉、孙吴长期对峙。曹氏历经曹丕、曹叡及曹芳、曹髦、曹奂五帝；高平陵之变后司马氏掌握朝政，266年曹奂禅位于司马炎，曹魏为西晋取代。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, precision = EXCLUDED.precision, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, end_year, end_month, start_abs, end_abs, precision, color_token, parent_id, group_id, note)
VALUES ('shu', '蜀汉', ARRAY['蜀','季汉'], 'cn', 'east_asia', 221, 5, 263, 12, 2656, 3167, 'month', 'ochre', NULL, 'sanguo', '221年刘备在成都称帝，国号汉，后世称蜀汉或季汉，以益州为核心、成都为都，立国主张承续汉统。刘备死后刘禅在位，诸葛亮等主持政务并多次北伐；蜀汉长期与曹魏交战，263年魏军入蜀、刘禅投降，王朝结束。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, precision = EXCLUDED.precision, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, end_year, end_month, start_abs, end_abs, precision, color_token, parent_id, group_id, note)
VALUES ('wu', '孙吴', ARRAY['吴'], 'cn', 'east_asia', 222, 10, 280, 5, 2673, 3364, 'month', 'ochre', NULL, 'sanguo', '孙氏政权立足江东，孙权于222年受魏封吴王，229年称帝，后世称孙吴或东吴；建业是其主要都城，疆域包括长江下游及南方广大地区。孙权之后由孙亮、孙休、孙皓相继即位，孙吴在三国中延续最久，280年孙皓向西晋投降，政权灭亡。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, precision = EXCLUDED.precision, group_id = EXCLUDED.group_id, note = EXCLUDED.note;

